from unittest.mock import Mock

class HealthService:
    def __init__(self, client):
        self.client = client

    def is_ready(self):
        return self.client.get("/health")["status"] == "ok"

client = Mock()
client.get.return_value = {"status": "ok"}

service = HealthService(client)
print(service.is_ready())

client.get.assert_called_once_with("/health")

